ls -la figures/analysis analysis.ipynb && python - <<'EOF'
import nbformat
nb = nbformat.read("analysis.ipynb", 4)
print(nb.cells[0].source[:300], "...\n")
print([l for l in nb.cells[7].source.splitlines() if "550" in l])
c = nb.cells[4]; print(c.outputs[0]["text"][:700])
# one-output-type-per-cell check
for i, c in enumerate(nb.cells):
    if c.cell_type == "code":
        kinds = {o.output_type for o in c.outputs}
        if "display_data" in kinds and "stream" in kinds: print("MIXED output in cell", i)
print("mixed-output check done")
EOF

python - <<'EOF'
import nbformat, re
nbp = "analysis.ipynb"
nb = nbformat.read(nbp, 4)
for c in nb.cells:
    if c.cell_type == "markdown":
        c.source = "\n".join(re.sub(r"^#( |$)", "", l) for l in c.source.splitlines())
nbformat.write(nb, nbp)
for i, c in enumerate(nb.cells):
    if c.cell_type == "markdown":
        print(f"=== md cell {i} ===")
        print(c.source)
EOF
